SELECT EXISTS (
    SELECT 1
    FROM msg_imperador
    WHERE nr_pedido = {{ $('Normaliza').item.json.nr_pedido }}
      AND tipo = '{{ $('Normaliza').item.json.pedido_status }}'
      AND enviado = TRUE
) AS ja_enviado;

