const inboxId = 10;

const conversas = ($json.payload || [])
  .filter(c => Number(c.inbox_id) === inboxId)
  .sort((a, b) =>
    Number(b.last_activity_at || b.updated_at || b.id) -
    Number(a.last_activity_at || a.updated_at || a.id)
  );

const conversa = conversas[0];

return [{
  json: {
    conversa_existe: !!conversa,
    conversation_id: conversa?.id ?? null,
    inbox_id: conversa?.inbox_id ?? inboxId,
    status: conversa?.status ?? null,
    precisa_reabrir: !!conversa && conversa.status !== 'open'
  }
}];

let conversationId = null;

// Conversa já existente
if ($json.conversation_id) {
  conversationId = $json.conversation_id;
}

// Retorno do node que reabriu a conversa
else if ($json.payload?.conversation_id) {
  conversationId = $json.payload.conversation_id;
}

// Conversa recém-criada
else if ($json.id) {
  conversationId = $json.id;
}

if (!conversationId) {
  throw new Error('Não foi possível identificar o conversation_id');
}

return [{
  json: {
    conversation_id: Number(conversationId)
  }
}];

const telefoneNovo = $('Dados Chatwoot').item.json.cliente_telefone;
const inboxId = 10;

// Somente números
const novo = String(telefoneNovo).replace(/\D/g, '');

// DDD + últimos 8 dígitos
const dddNovo = novo.slice(2, 4);
const ultimos8Novo = novo.slice(-8);

const contatos = $json.payload || [];

const contato = contatos.find(c => {
  const telefone = String(c.phone_number || '').replace(/\D/g, '');

  const ddd = telefone.slice(2, 4);
  const ultimos8 = telefone.slice(-8);

  return (
    ddd === dddNovo &&
    ultimos8 === ultimos8Novo
  );
});

// Procura especificamente a associação com a Inbox 10
const contactInbox = contato?.contact_inboxes?.find(
  ci => Number(ci.inbox?.id) === inboxId
);

return [{
  json: {
    contato_existe: !!contato,
    contact_id: contato?.id ?? null,
    source_id: contactInbox?.source_id ?? null
  }
}];
